INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p060:source_page','source_text','en','ENGINE

CYLINDER HEAD GASKET

Service repair no - 12.29.02

Remove

    1. Disconnect battery earth lead.
    2. Remove bonnet. See BODY, Exterior
       fittings.
    3. Remove air cleaner. See ENGINE
       MANAGEMENT SYSTEM - MEMS, Repairs.
    4. Remove front pipe to manifold gasket. See
       MANIFOLD & EXHAUST SYSTEMS, Repairs.




                                                         10. Disconnect multiplug from MAP sensor.




    5. Release throttle cable adjustment nut from
       abutment bracket.
    6. Disconnect throttle cable from throttle cam and
       position aside.




                                                         11. Disconnect 2 multiplugs from fuel injectors.




    7. Depress plastic collar on quick fit connector
       and disconnect brake servo vacuum pipe from
       inlet manifold.
    8. Disconnect multiplug from TP sensor.
    9. Disconnect multiplug from IACV.




6         REPAIRS','source','source_extraction','en','Exact text-layer extraction from source PDF; line breaks/column spacing preserved as extracted.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
