INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p067:source_page','source_text','en','ENGINE

VALVE

Service repair no - 12.29.59

Remove




  1. Remove cylinder head. See this section.
  2. Remove bolt securing engine breather pipe to
     cylinder head.
  3. Remove 6 nuts securing inlet and exhaust
     manifolds to cylinder head.
  4. Remove inlet and exhaust manifolds.
  5. Remove and discard manifold gasket.
  6. Remove inlet manifold locating rings.
  7. Remove 4 spark plugs.




                                                             REPAIRS   13','source','source_extraction','en','Exact text-layer extraction from source PDF; line breaks/column spacing preserved as extracted.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
