INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p069:source_page','source_text','en','ENGINE

ENGINE AND GEARBOX

Service repair no - 12.37.01/99

Remove

  1. Disconnect battery earth lead.
  2. Raise front of vehicle.

      WARNING: Support on safety stands.


 3. Drain engine oil. See
    MAINTENANCEMaintenance.
 4. Fit new sealing washer to drain plug.
 5. Fit drain plug and tighten to 34 Nm.
 6. Remove bonnet. See BODY, Exterior
    fittings.
 7. Remove radiator. See COOLING SYSTEM,
    Repairs.
 8. Remove engine steady bar - upper. See this
    section.
 9. Remove ECM. See ENGINE MANAGEMENT
    SYSTEM - MEMS, Repairs.
10. Remove servo and mounting bracket
    assembly. See BRAKES, Repairs.
11. Remove starter motor. See ELECTRICAL,
    Repairs.
12. Remove horn. See ELECTRICAL, Repairs.

                                                 13. Remove cover from engine compartment fuse
                                                     box.
                                                 14. Remove fusible link.
                                                 15. Release retaining tag and disconnect engine
                                                     harness lead from fuse box.
                                                 16. Release engine compartment fuse box from
                                                     ECM mounting bracket.




                                                                                REPAIRS       15','source','source_extraction','en','Exact text-layer extraction from source PDF; line breaks/column spacing preserved as extracted.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
