INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p083:source_page','source_text','en','ENGINE

FLYWHEEL HOUSING GASKET

Service repair no - 12.53.04

Remove

  1. Drain engine/gearbox oil. See
     MAINTENANCEMaintenance.
  2. Remove brake master cylinder. See BRAKES,
     Repairs.
  3. Remove clutch assembly and release bearing.
     See CLUTCH, Repairs.




                                                    5. Fit protective sleeve 18G 1043 to primary gear
                                                       splines.




  4. Loosen unions and disconnect brake pipes
     from pressure reducing valve.

      CAUTION: Plug the connections.




                                                    6. Remove nut and bolt securing steady bar to
                                                       body.
                                                    7. Release earth strap from body.
                                                    8. Remove bolt securing steady bar to engine and
                                                       collect washers.
                                                    9. Remove bolt securing engine steady bar
                                                       bracket to engine and remove bracket.
                                                   10. Remove engine steady bar and earth strap.




                                                                                   REPAIRS        29','source','source_extraction','en','Exact text-layer extraction from source PDF; line breaks/column spacing preserved as extracted.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
