INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p096:source_page','source_text','en','ENGINE

TIMING CHAIN TENSIONER

Service repair no - 12.65.28

Remove

  1. Remove timing gear cover. See this section.




  2. Remove 2 bolts securing timing chain
     tensioner to engine.
  3. Remove tensioner.

Refit

  1. Fit tensioner and tension the chain by applying
     firm pressure on the tensioner.
  2. Fit bolts securing tensioner to engine and
     tighten to 22 Nm.
  3. Fit timing gear cover. See this section.




42      REPAIRS                                        ISSUED: 12/96','source','source_extraction','en','Exact text-layer extraction from source PDF; line breaks/column spacing preserved as extracted.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
